from smart_contracts.deploy_common import deploy_typed


# Deploys ShipmentState, funds it for box storage and records its app id in
# smart_contracts/artifacts/deployed_apps.json (read by the API).
# The typed client is generated by `algokit project run build`.
def deploy() -> None:
    from smart_contracts.artifacts.shipment_state.shipment_state_client import (
        ShipmentStateFactory,
    )

    deploy_typed("shipment_state", ShipmentStateFactory)
